public static int[] reverse(int[] list) {
    int[] result = new int[list.length];
    for (int i = 0; i < list.length; i++)
        result[i] = list[list.length - 1 - i];
    return result;
}

int[] original = {1, 2, 3, 4, 5};
int[] reversed = reverse(original);
// reversed is {5, 4, 3, 2, 1}
